import 'dart:convert';

import '../commands.dart';
import '../engine/game_engine.dart';
import '../events.dart';
import '../model/game_state.dart';
import '../model/setup.dart';

/// Setup (incl. seed) + command log = the complete game. Events are
/// regenerated by re-running the engine.
final class Replay {
  const Replay({required this.setup, required this.commands});

  static const formatVersion = 1;

  final GameSetup setup;
  final List<Command> commands;

  Map<String, Object?> toJson() => {
    'format': 'fuse-replay',
    'version': formatVersion,
    'setup': setup.toJson(),
    'commands': [for (final c in commands) c.toJson()],
  };

  factory Replay.fromJson(Map<String, Object?> j) {
    final version = (j['version'] as num?)?.toInt();
    if (j['format'] != 'fuse-replay' || version == null) {
      throw const FormatException('Not a fuse replay');
    }
    if (version > formatVersion) {
      throw FormatException('Replay version $version is newer than supported');
    }
    return Replay(
      setup: GameSetup.fromJson(j['setup'] as Map<String, Object?>),
      commands: [
        for (final c in j['commands'] as List<Object?>)
          Command.fromJson(c as Map<String, Object?>),
      ],
    );
  }

  String encode({bool pretty = false}) =>
      (pretty ? const JsonEncoder.withIndent('  ') : const JsonEncoder())
          .convert(toJson());

  static Replay decode(String source) =>
      Replay.fromJson(jsonDecode(source) as Map<String, Object?>);

  /// Re-runs the game. [upTo] limits the number of commands applied (for
  /// step-through debugging).
  RecordedGame run({int? upTo}) {
    final game = RecordedGame(setup);
    final n = upTo == null || upTo > commands.length ? commands.length : upTo;
    for (var i = 0; i < n; i++) {
      game.apply(commands[i]);
    }
    return game;
  }
}

/// Host-side wrapper: current state + full command and event log.
final class RecordedGame {
  RecordedGame(this.setup) {
    final step = GameEngine.newGame(setup);
    _state = step.state;
    events.addAll(step.events);
  }

  final GameSetup setup;
  late GameState _state;
  final List<Command> commands = [];
  final List<GameEvent> events = [];

  GameState get state => _state;

  EngineStep apply(Command command) {
    final step = GameEngine.apply(_state, command);
    commands.add(command);
    events.addAll(step.events);
    _state = step.state;
    return step;
  }

  Replay get replay => Replay(setup: setup, commands: List.of(commands));
}
